@Composable fun TodayScreen(m:DressModel,n:Navigator) {
    Page {
        Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.Top){Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(7.dp)){Eyebrow("Your daily style forecast");Row(Modifier.clickable{n.open("locations")},verticalAlignment=Alignment.CenterVertically){EditorialText(m.p.city.name,32);Icon(Icons.Outlined.ExpandMore,"Choose location",Modifier.size(18.dp),tint=Ink)}};CircleAction(Icons.Outlined.Refresh,"Refresh weather"){m.refresh()}}
