            val planned=m.planned(LocalDate.now(ZoneId.of(m.p.city.zone)).toString())
            if(m.studioAvailable && planned!=null) GlassCard {Row(verticalAlignment=Alignment.CenterVertically){Caption("Planned for today: ${planned.style.label}",Modifier.weight(1f));if(planned.style!=m.p.style)TextButton({m.edit{it.copy(style=planned.style)}}){Text("Use plan")}}}
            Eyebrow("${m.p.style.label}  /  ${o.range}")
            Box(Modifier.clickable(role=Role.Button){n.open(Destination("outfit",weather=w,style=m.p.style))}) {OutfitPhoto(m,o,full=true,variant=planned?.takeIf{m.studioAvailable && it.style==m.p.style}?.variant);CircleAction(Icons.Outlined.NorthEast,"View today’s outfit",Modifier.align(Alignment.BottomEnd).padding(16.dp)){n.open(Destination("outfit",weather=w,style=m.p.style))}}
            Column(verticalArrangement=Arrangement.spacedBy(10.dp)){Eyebrow("What to wear today");EditorialText(o.title,36);Body(o.items.joinToString(", "){it.name}+".")}
            OccasionPicker(m.p.style){s->m.edit{it.copy(style=s)}}
            o.caution?.let{Caption("△  $it",Modifier.background(Color(0xFFFFE7BF),RoundedCornerShape(20.dp)).padding(16.dp),Ink)}
            GlassCard {Eyebrow("Wear this. Bring that.");o.items.take(3).forEach {item->ItemRow(item)};if(o.bring.isNotEmpty()){DividerLine();Eyebrow("TAKE WITH YOU");Text(o.bring.joinToString("  ·  "),color=Olive)}}
            val hours=m.upcoming.take(24)
            if(hours.isNotEmpty()) {
                var selectedHour by rememberSaveable{mutableFloatStateOf(0f)};val hour=hours[selectedHour.toInt().coerceIn(hours.indices)]
                GlassCard {Eyebrow("The day, dressed");Row(verticalAlignment=Alignment.CenterVertically){EditorialText(m.date(hour.time),32,Modifier.weight(1f));WeatherIcon(hour.conditions);EditorialText(m.temperature(hour.conditions.temperature),32)};Text(m.outfit(hour.conditions).items.first().name,color=Ink);if(hours.size>1)Slider(selectedHour,{selectedHour=it},valueRange=0f..hours.lastIndex.toFloat(),steps=max(0,hours.size-2),colors=SliderDefaults.colors(thumbColor=Olive,activeTrackColor=Olive),modifier=Modifier.semantics{contentDescription="Explore outfits through the day"});Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Caption(m.date(hours.first().time));Caption(m.date(hours.last().time))}}
                GlassCard {Row {Eyebrow("The next 24 hours",Modifier.weight(1f));Caption("All days",Modifier.clickable{n.selectTab("Forecast")})};Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(24.dp)){hours.forEach{h->Column(Modifier.clickable{n.open(Destination("outfit",weather=h.conditions,style=m.p.style))},horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(13.dp)){Caption(m.date(h.time));WeatherIcon(h.conditions,23.dp);Text(m.temperature(h.conditions.temperature),color=Ink,fontSize=15.sp);Caption("${rounded(h.conditions.windKmh)} km/h")}}}}
            }
            GlassCard {Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Metric("WIND","${rounded(w.windKmh)} km/h");Metric("HUMIDITY","${rounded(w.humidity)}%");Metric("PRECIPITATION","${String.format(java.util.Locale.US,"%.1f",w.precipitationMm)} mm")}}
            GlassCard {Eyebrow("Make it feel like you");EditorialText("How do these layers feel?",26);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("Too cold" to 1.0,"Just right" to 0.0,"Too warm" to -1.0).forEach{(label,amount)->Action(label,Modifier.weight(1f)){m.feedback(amount)}}};m.message?.let{Caption(it,color=Olive)}}
            m.forecast?.let{f->Caption("${if(f.sample)"Sample edition"else"Forecast updated"} · ${m.date(f.updatedAt,"MMM d, HH:mm")}\nFeels-like temperatures are estimates. Check local official alerts before outdoor plans.")};Attribution()
        }
    }
