@Composable fun Metric(label:String,value:String){Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text(label,fontSize=8.sp,letterSpacing=1.sp,color=Muted);Text(value,fontSize=13.sp,color=Ink)}}
