@Composable fun ForecastScreen(m:DressModel,n:Navigator) {Page {
    Heading("${m.p.city.name} · the days ahead","Forecast your\nwardrobe.");if(m.forecast?.sample==true)SampleLabel()
    if(m.forecast==null)EmptyForecast(m)else {
        m.days.getOrNull(1)?.let{d->Box{OutfitPhoto(m,m.outfit(d.representative.conditions),240.dp,1);Eyebrow("TOMORROW’S EDIT",Modifier.align(Alignment.BottomStart).padding(14.dp).background(Color.White.copy(alpha=.75f),CircleShape).padding(12.dp))}}
        Body("Hourly detail first. A wider view after that. Tap a day for its weather and layers.")
        val hours=m.upcoming.take(48)
        if(hours.isNotEmpty())GlassCard {Eyebrow("Temperature · next 48 hours");ForecastChart(hours,m);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){hours.filterIndexed{i,_->i%12==0}.forEach{Caption(m.date(it.time))}}}
        GlassCard {m.days.forEachIndexed{i,d->Row(Modifier.fillMaxWidth().clickable(role=Role.Button){n.open("day",d.date)}.padding(vertical=12.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(15.dp)){Column(Modifier.width(54.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text(m.dayTitle(d.date,"EEE"),fontWeight=FontWeight.SemiBold,color=Ink,fontSize=15.sp);Caption(m.dayTitle(d.date,"MMM d"))};WeatherIcon(d.representative.conditions,28.dp);Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(6.dp)){Caption(m.outfit(d.representative.conditions).items.first().name,color=Ink);Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(8.dp)){Caption(m.temperature(d.low));Box(Modifier.weight(1f).height(4.dp).clip(CircleShape).background(Brush.horizontalGradient(listOf(Olive.copy(alpha=.4f),Color(0xFFF3AD52)))));Caption(m.temperature(d.high))}};Icon(Icons.Outlined.ChevronRight,null,Modifier.size(15.dp),tint=Muted)};if(i<m.days.lastIndex)DividerLine()}}
        Caption("Daily high / low values are ranges across available forecast samples. Today may cover only the remaining hours. Later dates use six-hour intervals, so brief changes may not appear.");Attribution()
    }
}}
@Composable fun ForecastChart(hours:List<Hour>,m:DressModel) {val values=hours.map{if(m.p.fahrenheit)it.conditions.temperature*9/5+32 else it.conditions.temperature};val low=(values.minOrNull()?:0.0)-1;val high=(values.maxOrNull()?:1.0)+1
    Canvas(Modifier.fillMaxWidth().height(155.dp).semantics{contentDescription="Temperature forecast for the next 48 hours"}){val h=size.height-12.dp.toPx();val points=values.mapIndexed{i,v->Offset(i.toFloat()/max(1,values.lastIndex)*size.width,(1-(v-low)/(high-low)).toFloat()*h)};for(i in 0..3){val y=i*h/3;drawLine(Muted.copy(alpha=.15f),Offset(0f,y),Offset(size.width,y),1f)};if(points.isNotEmpty()){val line=Path().apply{moveTo(points.first().x,points.first().y);points.drop(1).forEach{lineTo(it.x,it.y)}};val fill=Path().apply{addPath(line);lineTo(size.width,h);lineTo(0f,h);close()};drawPath(fill,Brush.verticalGradient(listOf(Olive.copy(alpha=.25f),Color.Transparent)));drawPath(line,Olive,style=androidx.compose.ui.graphics.drawscope.Stroke(2.dp.toPx()))}}
}
@Composable fun DayScreen(m:DressModel,n:Navigator,date:String){val d=m.days.firstOrNull{it.date==date};Page{Heading(m.p.city.name,m.dayTitle(date));if(d!=null){OutfitPhoto(m,m.outfit(d.representative.conditions));d.hours.forEach{h->Row(Modifier.fillMaxWidth().clickable{n.open(Destination("outfit",weather=h.conditions,style=m.p.style))}.padding(vertical=8.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(15.dp)){Caption(m.date(h.time),Modifier.width(55.dp));WeatherIcon(h.conditions,23.dp);Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(5.dp)){Text(m.outfit(h.conditions).items.first().name,color=Ink,fontSize=15.sp);Caption("${h.intervalHours}-hour interval · ${h.conditions.label}")};EditorialText(m.temperature(h.conditions.temperature),26)};DividerLine()}}}}
@Composable fun OutfitScreen(m:DressModel,n:Navigator,d:Destination) {val w=d.weather?:return;var variant by rememberSaveable{mutableIntStateOf(0)};var adjustment by rememberSaveable{mutableDoubleStateOf(0.0)};var profile by rememberSaveable{mutableStateOf("Both")};var saved by rememberSaveable{mutableStateOf(false)};val comfort=(d.comfort?:m.p.comfort)+adjustment;val o=m.outfit(w,d.style,comfort);val context=LocalContext.current
    Page {OutfitPhoto(m,o,full=true,variant=variant);Action("Another look",Modifier.fillMaxWidth(),icon=Icons.Outlined.Shuffle){variant=(variant+1)%4};Heading("${d.style.label} · ${o.range}",o.title);Segmented(listOf("Both","Women","Men"),profile,{profile=it});Caption(if(profile=="Both")"A coordinated foundation for both wardrobes."else "A ${profile.lowercase()}’s outfit foundation. Adapt the fit and silhouette to your taste.");o.items.forEach{item->ItemRow(item,if(profile=="Men")item.name.replace(" / midi skirt","").replace(" / airy dress","").replace(" / airy blouse","").replace(" / shorts"," / tailored shorts")else item.name)};if(o.bring.isNotEmpty())GlassCard{Eyebrow("A few things to bring");Text(o.bring.joinToString(" · "),color=Ink)}
        if(m.studioAvailable && m.p.wardrobe.isNotEmpty())GlassCard {Eyebrow("From your own wardrobe");WardrobeMatcher.match(o,w,m.p.wardrobe).forEach{match->Column(verticalArrangement=Arrangement.spacedBy(4.dp)){Text("${if(match.garment==null)"⊕"else"✓"}  ${match.name}",color=Ink);Caption(if(match.garment==null)"A suggestion to add"else"You own this")}}}
        GlassCard{Eyebrow("Why this works");Text(o.explanation,color=Ink);o.caution?.let{Caption("△ $it",color=Color(0xFF92620B))}};Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Action("Warmer"){adjustment=min(6.0,adjustment+3)};Action("Lighter"){adjustment=max(-6.0,adjustment-3)};if(adjustment!=0.0)TextButton({adjustment=0.0}){Text("Reset")}};Action(if(saved)"Saved to your looks"else"Save this look",Modifier.fillMaxWidth(),enabled=!saved,primary=true,icon=Icons.Outlined.BookmarkBorder){m.saveLook(w,d.style,comfort);saved=true};Action("Share the outfit checklist",Modifier.fillMaxWidth(),icon=Icons.Outlined.IosShare){shareText(context,"${o.title} — Dress by the Weather\n${o.items.joinToString(", "){it.name}}\nBring: ${o.bring.joinToString(", ")}")};Caption("Styling guidance for adults. These are suggested layers, not a guarantee of comfort or protection.")
    }
}
@Composable fun LooksScreen(m:DressModel,n:Navigator){var collection by rememberSaveable{mutableStateOf("For today")};Page{Heading("A wardrobe, weather considered","The looks edit.");ProCard(m,n);Segmented(listOf("For today","Saved looks"),collection,{collection=it});if(collection=="Saved looks") {if(m.p.looks.isEmpty())GlassCard{EditorialText("Your personal collection",27);Body("Save a look to keep its clothing checklist here.")};m.p.looks.forEach{look->Column(verticalArrangement=Arrangement.spacedBy(14.dp)){Box(Modifier.clickable{n.open(Destination("outfit",weather=look.conditions,style=look.style,comfort=look.comfort))}){OutfitPhoto(m,m.outfit(look.conditions,look.style,look.comfort),220.dp)};Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(5.dp)){Eyebrow("${look.city} · ${look.style.label}");EditorialText(m.outfit(look.conditions,look.style,look.comfort).title,25)};IconButton({m.edit{it.copy(looks=it.looks.filterNot{s->s.id==look.id})}}){Icon(Icons.Outlined.DeleteOutline,"Delete saved look",tint=Muted)}}}}}else {val w=m.current;if(w==null)EmptyForecast(m)else{Body("Four ways to dress for the same forecast. Choose the occasion; we’ll consider the layers.");Occasion.entries.forEach{s->val o=m.outfit(w,s);Column(Modifier.clickable{n.open(Destination("outfit",weather=w,style=s))},verticalArrangement=Arrangement.spacedBy(14.dp)){OutfitPhoto(m,o,230.dp);Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(6.dp)){Eyebrow(s.label);EditorialText(o.items.first().name,28)};Icon(Icons.Outlined.NorthEast,null,tint=Ink)};Caption(o.items.joinToString(" · "){it.name})}}}}}}
@Composable fun LocationsScreen(m:DressModel,n:Navigator,mode:String){var query by rememberSaveable{mutableStateOf("")};LaunchedEffect(Unit){m.search(query)}
    fun choose(city:City){if(mode=="tripDestination"){n.tripCity=city;n.back()}else{m.select(city);n.back()}}
    Page{OutlinedTextField(query,{query=it;m.search(it)},Modifier.fillMaxWidth(),placeholder={Text("Search a city, address or destination")},leadingIcon={Icon(Icons.Outlined.Search,null)},singleLine=true,shape=RoundedCornerShape(18.dp));if(mode!="tripDestination"){FormCard{FormRow(if(m.locating)"Finding your location…"else"Use current location",icon=Icons.Outlined.NearMe){n.location();n.back()};Caption("Optional. Choose any city without sharing your device location.")}}
        if(query.isNotBlank()){SectionLabel("Search results");if(m.searching)CircularProgressIndicator(color=Olive);m.searchError?.let{Caption(it)};FormCard{m.searchResults.forEach{city->FormRow(city.name,city.zone.replace('_',' '),Icons.Outlined.Place){choose(city)}}}}else{SectionLabel("Your places");FormCard{m.p.cities.forEach{city->Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f).clickable{choose(city)}.padding(vertical=10.dp)){Text(city.name,color=Ink);Caption(city.zone.replace('_',' '))};if(city.id==m.p.city.id)Icon(Icons.Outlined.Check,null,tint=Olive)else IconButton({m.edit{it.copy(cities=it.cities.filterNot{c->c.id==city.id})}}){Icon(Icons.Outlined.DeleteOutline,"Remove saved place",tint=Muted)}}}};SectionLabel("Around the world");FormCard{City.suggestions.filter{c->m.p.cities.none{it.id==c.id}}.forEach{city->FormRow(city.name,city.zone.replace('_',' '),Icons.Outlined.Place){choose(city)}}}}
    }
}
